// Pre-rasterised IBM Plex Mono fonts for the idle renderer. Data: idle_fonts_data.cpp (generated by
// firmware/scripts/gen_idle_fonts.py). Ids / sizes / charsets: idle_layout.h and docs/idle-mode.md.
#pragma once

#include <stddef.h>
#include <stdint.h>

namespace idle {

struct Glyph {
    uint32_t off;  // into Font::bitmap; rows are ceil(w/8) bytes, MSB first, 1 = ink
    uint8_t w, h;
    uint8_t adv;
    int8_t xo;  // left edge relative to the pen
    int8_t yo;  // top edge relative to the baseline (negative = above)
};

struct Font {
    const uint8_t *bitmap;
    const Glyph *glyphs;
    const uint8_t *codes;  // sorted, one per glyph
    uint8_t n;
    uint8_t px;      // em size in pixels
    uint8_t ascent;  // baseline to top of the line box
    uint8_t lineH;   // line box height
    const Glyph *find(uint8_t code) const
    {
        for (size_t lo = 0, hi = n; lo < hi;) {
            size_t m = (lo + hi) / 2;
            if (codes[m] == code) return &glyphs[m];
            if (codes[m] < code) lo = m + 1; else hi = m;
        }
        return nullptr;
    }
};

constexpr size_t FONT_SLOTS = 19;
extern const Font *const kFontById[FONT_SLOTS];  // nullptr for ids that do not exist

inline const Font *fontById(uint8_t id) { return id < FONT_SLOTS ? kFontById[id] : nullptr; }

}  // namespace idle
